// The sea itself: water, light, parallax silhouettes, seabed and foreground.
// Everything is pixel art generated by code and cached where it is static.

import { CONFIG, VIEW_H, VIEW_W } from '../config';
import { hash3, hashFloat, seededRandom, valueNoise1D } from '../core/RNG';
import { biomeIndexAt, lightRaysAt, paletteAt, type BiomePalette } from '../world/Biomes';
import { LIVE_DECOR, type Decor, type Terrain } from '../world/Terrain';
import { hexToRgb, mixColor, shade } from './Color';
import { decorSprite, glowSprite, makeCanvas, Painter } from './PixelArt';

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5];
const bayer = (x: number, y: number) => BAYER[((y & 3) << 2) | (x & 3)];
const CHUNK_PAD = 72;
const GROUND_DEPTH = 230;

interface ChunkImage {
  canvas: HTMLCanvasElement;
  x0: number;
  top: number;
}

type Feature = 'mound' | 'spire' | 'kelp' | 'column' | 'hull' | 'tree' | 'crystal' | 'arch';
/** Silhouette features per biome (reef, rocky, wreck, forest, abyss). */
const BIOME_FEATURES: Feature[][] = [
  ['mound', 'mound', 'arch'],
  ['spire', 'kelp', 'spire', 'arch'],
  ['column', 'hull', 'spire', 'column'],
  ['tree', 'kelp', 'tree'],
  ['crystal', 'arch', 'crystal', 'spire'],
];

export class Scenery {
  private chunkImages = new Map<number, ChunkImage>();
  private waterKey = '';
  private waterPattern: CanvasPattern | null = null;
  private caustics: CanvasPattern[] = [];
  private causticCanvases: HTMLCanvasElement[] = [];
  private rays: HTMLCanvasElement | null = null;
  private vignette: HTMLCanvasElement | null = null;
  private builtFor = 0;
  private decorCache = new Map<number, HTMLCanvasElement>();
  private snow: { x: number; y: number; s: number; d: number }[] = [];
  private motes: { x: number; y: number; s: number; d: number }[] = [];

  constructor(private ctx: CanvasRenderingContext2D) {
    for (let i = 0; i < 80; i++) this.snow.push({ x: Math.random(), y: Math.random(), s: 0.3 + Math.random() * 0.7, d: Math.random() });
    for (let i = 0; i < 10; i++) this.motes.push({ x: Math.random(), y: Math.random(), s: 1.25 + Math.random() * 0.4, d: Math.random() });
    this.buildCaustics();
  }

  reset(): void {
    this.chunkImages.clear();
    this.decorCache.clear();
  }

  /** Rebuild the width-dependent caches when the internal width changes. */
  private ensureSize(): void {
    if (this.builtFor === VIEW_W) return;
    this.builtFor = VIEW_W;
    this.rays = this.buildRays();
    this.vignette = this.buildVignette();
    this.waterKey = '';
  }

  // ───────────────────────── background

  drawBackground(camX: number, camY: number, t: number): void {
    this.ensureSize();
    const mid = camX + VIEW_W / 2;
    const pal = paletteAt(mid);
    const light = lightRaysAt(mid);
    this.drawWater(pal);
    if (light > 0.02) this.drawCaustics(camX * 0.3, camY * 0.3, t, 0.035 * light, 0, VIEW_H * 0.6);
    this.drawRays(camX, t, light);
    this.drawLayers(camX, camY, pal, t);
    this.drawSnow(camX, t, pal, light);
    if (light > 0.05) this.drawSurface(t, light);
  }

  private drawWater(pal: BiomePalette): void {
    const key = pal.waterTop + pal.waterBottom;
    if (key !== this.waterKey || !this.waterPattern) {
      this.waterKey = key;
      const c = makeCanvas(4, VIEW_H);
      const g = c.getContext('2d')!;
      const img = g.createImageData(4, VIEW_H);
      const top = hexToRgb(pal.waterTop);
      const bot = hexToRgb(pal.waterBottom);
      const deep = hexToRgb(shade(pal.waterBottom, -0.35));
      const bands = 28;
      for (let y = 0; y < VIEW_H; y++) {
        const f = (y / VIEW_H) * bands;
        const band = Math.floor(f);
        for (let x = 0; x < 4; x++) {
          const k = Math.min(1, (band + (f - band > bayer(x, y) / 16 ? 1 : 0)) / bands);
          // two-stage gradient: top -> bottom, then darker near the floor
          const a = k < 0.7 ? top : bot;
          const b = k < 0.7 ? bot : deep;
          const kk = k < 0.7 ? k / 0.7 : (k - 0.7) / 0.3;
          const i = (y * 4 + x) * 4;
          img.data[i] = a[0] + (b[0] - a[0]) * kk;
          img.data[i + 1] = a[1] + (b[1] - a[1]) * kk;
          img.data[i + 2] = a[2] + (b[2] - a[2]) * kk;
          img.data[i + 3] = 255;
        }
      }
      g.putImageData(img, 0, 0);
      this.waterPattern = this.ctx.createPattern(c, 'repeat');
    }
    this.ctx.fillStyle = this.waterPattern!;
    this.ctx.fillRect(0, 0, VIEW_W, VIEW_H);
  }

  /** Tileable Voronoi-edge caustic texture, a few animation frames. */
  private buildCaustics(): void {
    const S = 64;
    const N = 20;
    const r = seededRandom(4242);
    const base = Array.from({ length: N }, () => ({ x: r() * S, y: r() * S, a: r() * Math.PI * 2, rad: 2 + r() * 3 }));
    const frames = 8;
    for (let f = 0; f < frames; f++) {
      const ph = (f / frames) * Math.PI * 2;
      const pts = base.map((p) => ({ x: p.x + Math.cos(ph + p.a) * p.rad, y: p.y + Math.sin(ph + p.a) * p.rad }));
      const c = makeCanvas(S, S);
      const g = c.getContext('2d')!;
      const img = g.createImageData(S, S);
      for (let y = 0; y < S; y++) {
        for (let x = 0; x < S; x++) {
          let d1 = 1e9;
          let d2 = 1e9;
          for (const p of pts) {
            let dx = Math.abs(x - p.x);
            let dy = Math.abs(y - p.y);
            if (dx > S / 2) dx = S - dx;
            if (dy > S / 2) dy = S - dy;
            const d = dx * dx + dy * dy;
            if (d < d1) { d2 = d1; d1 = d; } else if (d < d2) d2 = d;
          }
          const edge = Math.sqrt(d2) - Math.sqrt(d1);
          const v = edge < 0.8 ? 1 : edge < 1.5 ? 0.5 : 0;
          if (v > 0 && (v === 1 || bayer(x, y) < 8)) {
            const i = (y * S + x) * 4;
            img.data[i] = img.data[i + 1] = img.data[i + 2] = 255;
            img.data[i + 3] = 255;
          }
        }
      }
      g.putImageData(img, 0, 0);
      this.causticCanvases.push(c);
      this.caustics.push(this.ctx.createPattern(c, 'repeat')!);
    }
  }

  private drawCaustics(ox: number, oy: number, t: number, alpha: number, y0: number, y1: number): void {
    const ctx = this.ctx;
    const f = Math.floor(t * 7) % this.caustics.length;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = this.caustics[f];
    const tx = Math.round(-ox + t * 3) % 64;
    const ty = Math.round(-oy) % 64;
    ctx.translate(tx, ty);
    ctx.fillRect(-tx, y0 - ty, VIEW_W, y1 - y0);
    ctx.restore();
  }

  private buildRays(): HTMLCanvasElement {
    const c = makeCanvas(VIEW_W * 2, 230);
    const P = new Painter(c);
    const n = Math.round((VIEW_W * 2) / 110);
    for (let k = 0; k < n; k++) {
      const x0 = 20 + k * 110 + Math.round(hashFloat(k, 9) * 50);
      const w = 8 + Math.round(hashFloat(k, 3) * 26);
      for (let y = 0; y < 230; y++) {
        const fade = 1 - y / 230;
        for (let x = 0; x < w; x++) {
          // soft edges and fade via dithering
          const edge = Math.min(x, w - 1 - x) / (w / 2);
          if (bayer(x + x0, y) / 16 > fade * Math.min(1, edge * 2.5)) continue;
          P.ctx.fillStyle = '#ffffff';
          P.ctx.fillRect(x0 + Math.floor(y * 0.42) + x, y, 1, 1);
        }
      }
    }
    return c;
  }

  private drawRays(camX: number, t: number, amount: number): void {
    if (amount <= 0.02 || !this.rays) return;
    const ctx = this.ctx;
    const off = (((camX * 0.12 + Math.sin(t * 0.25) * 10) % VIEW_W) + VIEW_W) % VIEW_W;
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = (0.055 + 0.015 * Math.sin(t * 0.7)) * amount;
    ctx.drawImage(this.rays, -Math.round(off), 0);
    ctx.globalAlpha = 0.04 * amount;
    ctx.drawImage(this.rays, -Math.round((off * 1.6) % VIEW_W) - 40, 0);
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
  }

  /** Underside of the surface: wavy bright band at the very top (shallow water only). */
  private drawSurface(t: number, light: number): void {
    const ctx = this.ctx;
    for (let x = 0; x < VIEW_W; x += 2) {
      const y = Math.round(4 + Math.sin(x * 0.07 + t * 1.8) * 1.6 + Math.sin(x * 0.19 - t * 1.1) * 1.1);
      ctx.globalAlpha = 0.22 * light;
      ctx.fillStyle = '#e8ffff';
      ctx.fillRect(x, 0, 2, y);
      ctx.globalAlpha = 0.5 * light;
      ctx.fillRect(x, y, 2, 1);
      if (Math.sin(x * 0.5 + t * 3) > 0.92) {
        ctx.globalAlpha = 0.8 * light;
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(x, y - 1, 2, 1);
      }
    }
    ctx.globalAlpha = 1;
  }

  private drawLayers(camX: number, camY: number, pal: BiomePalette, t: number): void {
    const haze = pal.waterBottom;
    const layers = [
      { par: 0.12, base: 132, amp: 34, freq: 1 / 160, color: mixColor(pal.farSil, haze, 0.45), seed: 501, slot: 120, dens: 0.55, scale: 0.75 },
      { par: 0.3, base: 152, amp: 40, freq: 1 / 110, color: mixColor(pal.farSil, pal.midSil, 0.5), seed: 733, slot: 95, dens: 0.6, scale: 0.9 },
      { par: 0.55, base: 176, amp: 34, freq: 1 / 80, color: shade(pal.midSil, -0.12), seed: 977, slot: 80, dens: 0.55, scale: 1.1 },
    ];
    const ctx = this.ctx;
    for (const L of layers) {
      const yOff = Math.round(-camY * L.par * 0.25);
      const lx0 = camX * L.par;
      ctx.fillStyle = L.color;
      for (let x = 0; x < VIEW_W; x += 2) {
        const wx = lx0 + x;
        const n = valueNoise1D(L.seed, wx * L.freq) * 0.7 + valueNoise1D(L.seed + 1, wx * L.freq * 3.1) * 0.3;
        const top = Math.round(L.base - n * L.amp + yOff);
        ctx.fillRect(x, top, 2, VIEW_H - top);
      }
      // biome features on this layer
      const k0 = Math.floor((lx0 - 120) / L.slot);
      const k1 = Math.floor((lx0 + VIEW_W + 120) / L.slot);
      for (let k = k0; k <= k1; k++) {
        if (hashFloat(L.seed, k) > L.dens) continue;
        const worldX = (k * L.slot) / L.par;
        const biome = biomeIndexAt(worldX);
        const list = BIOME_FEATURES[biome];
        const type = list[Math.floor(hashFloat(L.seed, k, 3) * list.length)];
        const fx = Math.round(k * L.slot + hashFloat(L.seed, k, 5) * L.slot * 0.6 - lx0);
        const n = valueNoise1D(L.seed, (lx0 + fx) * L.freq) * 0.7 + valueNoise1D(L.seed + 1, (lx0 + fx) * L.freq * 3.1) * 0.3;
        const ground = Math.round(L.base - n * L.amp + yOff) + 4;
        this.drawFeature(type, fx, ground, L.scale, hash3(L.seed, k), L.color, pal, t, L.par);
      }
    }
  }

  private drawFeature(type: Feature, x: number, ground: number, s: number, seed: number, color: string, pal: BiomePalette, t: number, par: number): void {
    const ctx = this.ctx;
    const r = seededRandom(seed);
    ctx.fillStyle = color;
    switch (type) {
      case 'mound': {
        const w = Math.round((30 + r() * 40) * s);
        const h = Math.round((14 + r() * 22) * s);
        for (let i = 0; i < w; i += 2) {
          const k = Math.sin((i / w) * Math.PI);
          const bump = Math.round(Math.sin(i * 0.6 + seed) * 1.5);
          const top = ground - Math.round(Math.pow(k, 0.6) * h) + bump;
          ctx.fillRect(x + i - w / 2, top, 2, ground - top + 2);
        }
        // little branch silhouettes on top
        for (let b = 0; b < 3; b++) {
          const bx = Math.round(x - w / 3 + r() * w * 0.66);
          const bh = Math.round((5 + r() * 8) * s);
          ctx.fillRect(bx, ground - h - bh + 4, 1, bh);
          ctx.fillRect(bx - 2, ground - h - bh + 6, 2, 1);
          ctx.fillRect(bx + 1, ground - h - bh + 3, 2, 1);
        }
        break;
      }
      case 'spire': {
        const w = Math.round((12 + r() * 18) * s);
        const h = Math.round((40 + r() * 60) * s);
        for (let i = 0; i < w; i += 1) {
          const k = 1 - Math.abs(i / w - 0.5) * 2;
          const jag = (Math.floor(i / 2) * 7919 + seed) % 5;
          const top = ground - Math.round(Math.pow(k, 1.6) * h) + jag;
          ctx.fillRect(x + i - w / 2, top, 1, ground - top + 2);
        }
        break;
      }
      case 'arch': {
        const w = Math.round((50 + r() * 40) * s);
        const h = Math.round((30 + r() * 30) * s);
        const th = Math.round(8 * s) + 2;
        for (let i = 0; i < w; i += 2) {
          const k = Math.sin((i / w) * Math.PI);
          const top = ground - Math.round(k * h);
          const legs = i < th || i > w - th;
          ctx.fillRect(x + i - w / 2, top, 2, legs ? ground - top + 2 : th);
        }
        break;
      }
      case 'kelp': {
        const n = 2 + Math.floor(r() * 3);
        for (let j = 0; j < n; j++) {
          const kx = x + Math.round((j - n / 2) * 6 * s);
          const h = Math.round((60 + r() * 70) * s);
          const ph = r() * 6;
          for (let y = 0; y < h; y += 2) {
            const sway = Math.round(Math.sin(t * 0.8 + ph + y * 0.05) * (y / h) * 6 * s);
            ctx.fillRect(kx + sway, ground - y, 2, 2);
            if (y % 10 === 6) ctx.fillRect(kx + sway + (y % 20 === 6 ? 2 : -3), ground - y, 3, 2);
          }
        }
        break;
      }
      case 'column': {
        const w = Math.round((10 + r() * 8) * s);
        const h = Math.round((40 + r() * 45) * s);
        const broken = r() < 0.5;
        ctx.fillRect(x - w / 2, ground - h, w, h + 2);
        ctx.fillRect(x - w / 2 - 3, ground - 4, w + 6, 4);
        if (!broken) ctx.fillRect(x - w / 2 - 3, ground - h - 4, w + 6, 4);
        else {
          for (let i = 0; i < w; i += 2) ctx.fillRect(x - w / 2 + i, ground - h - ((i * 3 + seed) % 6), 2, 6);
        }
        break;
      }
      case 'hull': {
        const w = Math.round((80 + r() * 50) * s);
        const h = Math.round((22 + r() * 14) * s);
        const tilt = r() < 0.5 ? 1 : -1;
        for (let i = 0; i < w; i += 2) {
          const u = i / w;
          const deck = Math.round(h * (0.2 + tilt * (u - 0.5) * 0.4));
          const keel = Math.round(h - Math.pow(Math.abs(u - 0.45) * 2, 2.5) * h * 0.6);
          ctx.fillRect(x + i - w / 2, ground - h + deck, 2, Math.max(1, keel - deck + 2));
        }
        // mast
        ctx.fillRect(x + Math.round(w * 0.05), ground - h * 2.2, 2, h * 1.6);
        ctx.fillRect(x + Math.round(w * 0.05) - 8, ground - h * 1.9, 14, 2);
        break;
      }
      case 'tree': {
        const h = Math.round((70 + r() * 60) * s);
        const w = Math.round(4 * s) + 2;
        for (let y = 0; y < h; y += 2) {
          const sway = Math.round(Math.sin(t * 0.5 + seed + y * 0.03) * (y / h) * 4);
          ctx.fillRect(x + sway - w / 2, ground - y, w, 2);
          if (y > h * 0.4 && y % 14 === 0) {
            const len = Math.round((8 + r() * 10) * s);
            const dir = (y / 14) % 2 ? 1 : -1;
            ctx.fillRect(x + sway + (dir > 0 ? w / 2 : -w / 2 - len), ground - y, len, 2);
          }
        }
        // glowing bulbs
        ctx.fillStyle = mixColor(pal.glow, color, 0.35 + par * 0.3);
        for (let b = 0; b < 4; b++) {
          if (Math.sin(t * 1.5 + b + seed) < -0.6) continue;
          const by = ground - Math.round(h * (0.5 + r() * 0.5));
          const bx = x + Math.round((r() - 0.5) * 24 * s);
          ctx.fillRect(bx, by, 2, 2);
        }
        break;
      }
      case 'crystal': {
        const n = 2 + Math.floor(r() * 3);
        for (let j = 0; j < n; j++) {
          const cx = x + Math.round((j - n / 2) * 10 * s + r() * 6);
          const h = Math.round((30 + r() * 70) * s);
          const w = Math.round((6 + r() * 8) * s);
          const lean = (r() - 0.5) * 0.6;
          ctx.fillStyle = color;
          for (let y = 0; y < h; y++) {
            const k = y < h * 0.8 ? 1 : 1 - (y - h * 0.8) / (h * 0.2);
            const ww = Math.max(1, Math.round(w * k));
            ctx.fillRect(Math.round(cx + lean * y - ww / 2), ground - y, ww, 1);
          }
          // glowing edge on nearer layers
          if (par > 0.25) {
            ctx.fillStyle = mixColor(pal.glow, color, 0.55);
            for (let y = 2; y < h * 0.8; y += 2) ctx.fillRect(Math.round(cx + lean * y + w / 2 - 1), ground - y, 1, 1);
          }
        }
        break;
      }
    }
  }

  private drawSnow(camX: number, t: number, pal: BiomePalette, light: number): void {
    const ctx = this.ctx;
    ctx.fillStyle = pal.particle;
    ctx.globalAlpha = 0.55;
    for (const s of this.snow) {
      const x = (((s.x * VIEW_W - camX * 0.7 * s.s + Math.sin(t * 0.7 + s.d * 6) * 4) % VIEW_W) + VIEW_W) % VIEW_W;
      const y = (((s.y * VIEW_H + t * 6 * s.s) % VIEW_H) + VIEW_H) % VIEW_H;
      ctx.fillRect(Math.round(x), Math.round(y), 1, 1);
    }
    // deep water: drifting bioluminescent plankton
    if (light < 0.4) {
      ctx.fillStyle = pal.glow;
      for (let i = 0; i < 26; i++) {
        const s = this.snow[i];
        const blink = Math.sin(t * 2 + i * 1.7);
        if (blink < 0.2) continue;
        ctx.globalAlpha = 0.7 * blink * (1 - light);
        const x = (((s.d * VIEW_W - camX * 0.5 + Math.sin(t * 0.4 + i) * 10) % VIEW_W) + VIEW_W) % VIEW_W;
        const y = (((s.s * VIEW_H - t * 4) % VIEW_H) + VIEW_H) % VIEW_H;
        ctx.fillRect(Math.round(x), Math.round(y), 1, 1);
      }
    }
    ctx.globalAlpha = 1;
  }

  // ───────────────────────── seabed

  drawTerrain(terrain: Terrain, camX: number, camY: number, t: number): void {
    const ctx = this.ctx;
    const cw = CONFIG.terrain.chunkWidth;
    const first = Math.floor((camX - CHUNK_PAD) / cw);
    const last = Math.floor((camX + VIEW_W + CHUNK_PAD) / cw);
    for (let i = first; i <= last; i++) {
      if (i < -1) continue;
      const img = this.chunkImage(terrain, i);
      ctx.drawImage(img.canvas, img.x0 - CHUNK_PAD - camX, img.top - camY);
    }
    // dancing light on the sand (shallow) — clipped to the ground
    const light = lightRaysAt(camX + VIEW_W / 2);
    if (light > 0.02) {
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(0, VIEW_H);
      for (let x = 0; x <= VIEW_W; x += 4) ctx.lineTo(x, Math.round(terrain.seabedY(camX + x) - camY));
      ctx.lineTo(VIEW_W, VIEW_H);
      ctx.closePath();
      ctx.clip();
      this.drawCaustics(camX, camY, t, 0.07 * light, 0, VIEW_H);
      ctx.restore();
    }
    for (let i = first; i <= last; i++) if (i >= 0) this.drawLiveDecor(terrain, i, camX, camY, t, false);
  }

  drawFront(terrain: Terrain, camX: number, camY: number, t: number): void {
    const cw = CONFIG.terrain.chunkWidth;
    const first = Math.floor((camX - CHUNK_PAD) / cw);
    const last = Math.floor((camX + VIEW_W + CHUNK_PAD) / cw);
    for (let i = first; i <= last; i++) if (i >= 0) this.drawLiveDecor(terrain, i, camX, camY, t, true);
    this.drawForegroundSilhouettes(camX, t);
    this.drawMotes(camX, t);
    if (this.vignette) this.ctx.drawImage(this.vignette, 0, 0);
  }

  private chunkImage(terrain: Terrain, index: number): ChunkImage {
    let img = this.chunkImages.get(index);
    if (img) return img;
    const cw = CONFIG.terrain.chunkWidth;
    const x0 = index * cw;
    const chunk = index >= 0 ? terrain.getChunk(index) : { decor: [] as Decor[], crevices: [], index };
    let minY = Infinity;
    let maxY = -Infinity;
    for (let x = -CHUNK_PAD; x < cw + CHUNK_PAD; x += 4) {
      const y = terrain.seabedY(x0 + x);
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
    for (const d of chunk.decor) if (!LIVE_DECOR.has(d.type)) minY = Math.min(minY, d.y - d.h - 6);
    const top = Math.floor(minY - 10);
    const W = cw + CHUNK_PAD * 2;
    const H = Math.ceil(maxY + GROUND_DEPTH - top);
    const canvas = makeCanvas(W, H);
    const g = canvas.getContext('2d')!;
    const ox = CHUNK_PAD - x0;
    const oy = -top;

    const back = chunk.decor.filter((d) => d.type === 'rock' || d.type === 'coral' || d.type === 'ruin' || d.type === 'wreck');
    for (const d of back) {
      const s = decorSprite(d, paletteAt(d.x));
      g.drawImage(s, Math.round(d.x - d.w / 2 + ox), Math.round(d.y - d.h + oy));
    }
    g.drawImage(this.buildGround(terrain, x0, cw, top, H), CHUNK_PAD, 0);
    for (const d of chunk.decor) {
      if (d.type === 'crevice') g.drawImage(decorSprite(d, paletteAt(d.x)), Math.round(d.x - d.w / 2 + ox), Math.round(d.y + oy));
      else if (d.type === 'shell') g.drawImage(decorSprite(d, paletteAt(d.x)), Math.round(d.x - 2 + ox), Math.round(d.y - 3 + oy));
    }
    img = { canvas, x0, top };
    this.chunkImages.set(index, img);
    if (this.chunkImages.size > 12) for (const k of this.chunkImages.keys()) if (Math.abs(k - index) > 5) this.chunkImages.delete(k);
    return img;
  }

  /** Per-pixel seabed: rippled sand, strata, pebbles, rock patches, moss and crystals by biome. */
  private buildGround(terrain: Terrain, x0: number, cw: number, top: number, H: number): HTMLCanvasElement {
    const c = makeCanvas(cw, H);
    const g = c.getContext('2d')!;
    const img = g.createImageData(cw, H);
    const d = img.data;
    const seed = terrain.seed;
    const put = (x: number, y: number, rgb: [number, number, number]) => {
      if (y < 0 || y >= H) return;
      const i = (y * cw + x) * 4;
      d[i] = rgb[0]; d[i + 1] = rgb[1]; d[i + 2] = rgb[2]; d[i + 3] = 255;
    };
    for (let x = 0; x < cw; x++) {
      const wx = x0 + x;
      const p = paletteAt(wx);
      const biome = biomeIndexAt(wx);
      const light = hexToRgb(p.sandLight), mid = hexToRgb(p.sand), dark = hexToRgb(p.sandDark);
      const deep = hexToRgb(shade(p.sandDark, -0.28)), deeper = hexToRgb(shade(p.sandDark, -0.45));
      const rockL = hexToRgb(p.rockLight), rock = hexToRgb(shade(p.rock, -0.25)), rockD = hexToRgb(shade(p.rockDark, -0.2));
      const glow = hexToRgb(p.glow);
      const sy = Math.round(terrain.seabedY(wx)) - top;
      const rockiness = biome === 1 || biome === 4 ? 0.25 : biome === 2 ? 0.45 : 0.7;
      for (let y = sy; y < H; y++) {
        const dy = y - sy;
        let col: [number, number, number];
        if (dy === 0) col = light;
        else if (dy < 12) {
          // wind-blown ripples near the surface of the sand
          const rip = Math.sin(wx * 0.45 + dy * 1.3 + valueNoise1D(seed + 5, wx / 30) * 3);
          col = rip > 0.72 ? light : rip < -0.8 ? dark : mid;
          if (dy > 8 && bayer(wx, y) < (dy - 8) * 4) col = dark;
        } else if (dy < 46) {
          col = dark;
          if (dy > 40 && bayer(wx, y) < (dy - 40) * 3) col = deep;
        } else {
          col = (dy + Math.round(valueNoise1D(seed + 9, wx / 50) * 4)) % 16 === 0 ? dark : dy > 120 ? deeper : deep;
        }
        // embedded rock patches
        const rn = valueNoise1D(seed + 31, wx / 26) + valueNoise1D(seed + 37, y / 9) * 0.6;
        if (dy > 3 && rn > 0.55 + rockiness) col = rn > 0.85 + rockiness && dy < 30 ? rock : bayer(wx, y) < 10 ? rockD : rock;
        // speckles and pebbles fixed in world space
        const h = hashFloat(seed, wx, y + top);
        if (dy > 1 && h < 0.035) col = dy < 12 ? light : mid;
        else if (dy > 2 && h > 0.985) col = deeper;
        put(x, y, col);
      }
      // pebble clusters with highlights
      if (hashFloat(seed, wx, 77) < 0.05) {
        const py = sy + 3 + Math.floor(hashFloat(seed, wx, 78) * 20);
        put(x, py, rockL);
        if (x + 1 < cw) { put(x + 1, py, rock); put(x + 1, py + 1, rockD); }
        put(x, py + 1, rock);
      }
      // biome surface details
      if (biome === 0 && hashFloat(seed, wx, 91) < 0.18) {
        // seagrass tufts
        const gr = hexToRgb(p.weed);
        const hgt = 1 + Math.floor(hashFloat(seed, wx, 92) * 4);
        for (let k = 1; k <= hgt; k++) put(x, sy - k, k === hgt ? hexToRgb(shade(p.weed, 0.3)) : gr);
      }
      if (biome >= 3 && hashFloat(seed, wx, 93) < 0.12) {
        // glowing moss
        put(x, sy, glow);
        if (hashFloat(seed, wx, 94) < 0.4) put(x, sy - 1, glow);
      }
      if (biome === 2 && hashFloat(seed, wx, 95) < 0.04) {
        // rusty debris
        const rust = hexToRgb('#8a4a2a');
        put(x, sy + 1, rust);
        put(x, sy + 2, rust);
      }
    }
    g.putImageData(img, 0, 0);
    return c;
  }

  private cachedDecor(d: Decor): HTMLCanvasElement {
    let s = this.decorCache.get(d.seed);
    if (!s) {
      s = decorSprite(d, paletteAt(d.x));
      this.decorCache.set(d.seed, s);
      if (this.decorCache.size > 300) this.decorCache.clear();
    }
    return s;
  }

  private drawLiveDecor(terrain: Terrain, index: number, camX: number, camY: number, t: number, front: boolean): void {
    const ctx = this.ctx;
    const chunk = terrain.getChunk(index);
    for (const d of chunk.decor) {
      if (d.front !== front || !LIVE_DECOR.has(d.type)) continue;
      const sx = Math.round(d.x - camX);
      if (sx < -40 || sx > VIEW_W + 40) continue;
      const sy = Math.round(d.y - camY);
      const p = paletteAt(d.x);
      const ph = (d.seed % 1000) / 160;
      switch (d.type) {
        case 'weed': {
          const dark = shade(p.weed, -0.35);
          for (let i = 0; i < d.h; i++) {
            const f = i / d.h;
            const off = Math.round(Math.sin(t * 1.8 + ph + i * 0.18) * f * 3.5);
            ctx.fillStyle = i % 5 === 0 ? dark : p.weed;
            ctx.fillRect(sx + off, sy - i, 2, 1);
            if (i % 6 === 3) {
              ctx.fillStyle = p.weed;
              ctx.fillRect(sx + off + (i % 12 === 3 ? 2 : -1), sy - i, 1, 1);
            }
          }
          break;
        }
        case 'kelp': {
          const stalk = shade(p.weed, -0.25);
          const leaf = mixColor(p.weed, '#c8b040', 0.25);
          const leafD = shade(leaf, -0.3);
          for (let i = 0; i < d.h; i++) {
            const f = i / d.h;
            const off = Math.round(Math.sin(t * 1.1 + ph + i * 0.06) * f * 7 + Math.sin(t * 2.3 + i * 0.2) * f);
            ctx.fillStyle = stalk;
            ctx.fillRect(sx + off, sy - i, 1, 1);
            if (i % 7 === 3 && i > 4) {
              const dir = (i / 7) % 2 > 1 ? 1 : -1;
              const len = 3 + Math.round((1 - f) * 3);
              ctx.fillStyle = leaf;
              ctx.fillRect(dir > 0 ? sx + off + 1 : sx + off - len, sy - i, len, 2);
              ctx.fillStyle = leafD;
              ctx.fillRect(dir > 0 ? sx + off + len : sx + off - len, sy - i + 1, 1, 1);
            }
          }
          // gas bladder at the tip
          const tipOff = Math.round(Math.sin(t * 1.1 + ph + d.h * 0.06) * 7);
          ctx.fillStyle = leaf;
          ctx.fillRect(sx + tipOff - 1, sy - d.h - 2, 3, 3);
          break;
        }
        case 'anemone': {
          const col = [p.coralA, p.coralB, p.coralC][d.seed % 3];
          const tip = shade(col, 0.4);
          const n = Math.round(d.w / 2);
          for (let k = 0; k < n; k++) {
            const bx = sx - Math.round(d.w / 2) + k * 2;
            const len = d.h - Math.abs(k - n / 2);
            for (let i = 0; i < len; i++) {
              const off = Math.round(Math.sin(t * 2.4 + ph + k * 0.8 + i * 0.35) * (i / len) * 2.2);
              ctx.fillStyle = i === len - 1 ? tip : col;
              ctx.fillRect(bx + off, sy - 3 - i, 1, 1);
            }
          }
          ctx.fillStyle = shade(col, -0.35);
          ctx.fillRect(sx - Math.round(d.w / 2), sy - 3, d.w, 4);
          ctx.fillStyle = shade(col, -0.15);
          ctx.fillRect(sx - Math.round(d.w / 2) + 1, sy - 3, d.w - 2, 1);
          break;
        }
        case 'glowPlant': {
          const stalk = shade(p.weed, -0.4);
          let tipX = sx;
          for (let i = 0; i < d.h; i++) {
            tipX = sx + Math.round(Math.sin(t * 1.2 + ph + i * 0.12) * (i / d.h) * 2);
            ctx.fillStyle = stalk;
            ctx.fillRect(tipX, sy - i, 1, 1);
          }
          const pulse = 0.55 + 0.45 * Math.sin(t * 2.4 + ph);
          this.glow(tipX, sy - d.h, 7, p.glow, 0.5 * pulse);
          ctx.fillStyle = p.glow;
          ctx.fillRect(tipX - 1, sy - d.h - 1, 3, 2);
          ctx.fillStyle = '#ffffff';
          ctx.fillRect(tipX, sy - d.h - 1, 1, 1);
          break;
        }
        case 'crystal': {
          const s = this.cachedDecor(d);
          const pulse = 0.5 + 0.5 * Math.sin(t * 1.6 + ph);
          this.glow(sx, sy - d.h / 2, Math.max(d.w, d.h) * 0.7, p.glow, 0.25 + 0.2 * pulse);
          ctx.drawImage(s, Math.round(sx - d.w / 2), sy - d.h + 2);
          break;
        }
        case 'vent': {
          const s = this.cachedDecor(d);
          ctx.drawImage(s, Math.round(sx - d.w / 2), sy - d.h + 2);
          // heat shimmer + rising bubbles
          this.glow(sx, sy - d.h, 6, '#ff9a5a', 0.25 + 0.15 * Math.sin(t * 5 + ph));
          ctx.fillStyle = '#e8ffff';
          for (let b = 0; b < 6; b++) {
            const rise = (t * 26 + b * 13 + ph * 10) % 70;
            const bx = sx + Math.round(Math.sin(t * 3 + b) * (1 + rise * 0.06));
            const by = sy - d.h - Math.round(rise);
            ctx.globalAlpha = 1 - rise / 70;
            ctx.fillRect(bx, by, b % 3 === 0 ? 2 : 1, b % 3 === 0 ? 2 : 1);
          }
          ctx.globalAlpha = 1;
          break;
        }
      }
    }
  }

  private glow(x: number, y: number, r: number, color: string, alpha: number): void {
    const ctx = this.ctx;
    const g = glowSprite(r, color);
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = alpha;
    ctx.drawImage(g, Math.round(x - g.width / 2), Math.round(y - g.height / 2));
    ctx.globalAlpha = 1;
    ctx.globalCompositeOperation = 'source-over';
  }

  /** Dark close-up rocks and weeds passing along the bottom edge (depth framing). */
  private drawForegroundSilhouettes(camX: number, t: number): void {
    const ctx = this.ctx;
    const par = 1.45;
    const lx0 = camX * par;
    const slot = 120;
    const pal = paletteAt(camX + VIEW_W / 2);
    const col = mixColor(pal.rockDark, '#02060c', 0.55);
    const weed = mixColor(pal.weed, '#02060c', 0.6);
    const k0 = Math.floor((lx0 - 80) / slot);
    const k1 = Math.floor((lx0 + VIEW_W + 80) / slot);
    for (let k = k0; k <= k1; k++) {
      const h = hashFloat(k, 4441);
      if (h > 0.55) continue;
      const x = Math.round(k * slot + hashFloat(k, 4442) * 60 - lx0);
      if (h < 0.3) {
        const w = 26 + Math.round(hashFloat(k, 4443) * 40);
        const hh = 9 + Math.round(hashFloat(k, 4444) * 14);
        ctx.fillStyle = col;
        for (let i = 0; i < w; i += 2) {
          const top = VIEW_H - Math.round(Math.pow(Math.sin((i / w) * Math.PI), 0.7) * hh) + ((i * 7 + k) % 3);
          ctx.fillRect(x + i - w / 2, top, 2, VIEW_H - top);
        }
      } else {
        ctx.fillStyle = weed;
        for (let j = 0; j < 4; j++) {
          const bx = x + j * 4;
          const len = 14 + ((j * 13 + k * 7) % 14);
          for (let y = 0; y < len; y += 2) {
            const sway = Math.round(Math.sin(t * 1.6 + j + k + y * 0.15) * (y / len) * 4);
            ctx.fillRect(bx + sway, VIEW_H - y, 2, 2);
          }
        }
      }
    }
  }

  /** Big out-of-focus specks in front of everything. */
  private drawMotes(camX: number, t: number): void {
    const ctx = this.ctx;
    ctx.fillStyle = '#ffffff';
    for (const m of this.motes) {
      const x = (((m.x * VIEW_W - camX * m.s + Math.sin(t * 0.5 + m.d * 9) * 6) % VIEW_W) + VIEW_W) % VIEW_W;
      const y = (((m.y * VIEW_H + t * 3 * m.s) % VIEW_H) + VIEW_H) % VIEW_H;
      ctx.globalAlpha = 0.12;
      ctx.fillRect(Math.round(x) - 1, Math.round(y), 3, 1);
      ctx.fillRect(Math.round(x), Math.round(y) - 1, 1, 3);
    }
    ctx.globalAlpha = 1;
  }

  private buildVignette(): HTMLCanvasElement {
    const c = makeCanvas(VIEW_W, VIEW_H);
    const g = c.getContext('2d')!;
    const img = g.createImageData(VIEW_W, VIEW_H);
    for (let y = 0; y < VIEW_H; y++) {
      for (let x = 0; x < VIEW_W; x++) {
        const dx = (x - VIEW_W / 2) / (VIEW_W / 2);
        const dy = (y - VIEW_H / 2) / (VIEW_H / 2);
        const r = Math.sqrt(dx * dx * 0.7 + dy * dy * 0.9);
        const v = Math.max(0, (r - 0.9) * 1.8);
        if (v * 16 > bayer(x, y)) {
          const i = (y * VIEW_W + x) * 4;
          img.data[i] = 2; img.data[i + 1] = 8; img.data[i + 2] = 18;
          img.data[i + 3] = Math.min(110, 50 + v * 80);
        }
      }
    }
    g.putImageData(img, 0, 0);
    return c;
  }
}

